import { State } from '../util/state'
import type { CodeActionParams, CodeAction } from 'vscode-languageserver'
import {
  InvalidConfigPathDiagnostic,
  InvalidTailwindDirectiveDiagnostic,
  InvalidScreenDiagnostic,
  InvalidVariantDiagnostic,
  RecommendedVariantOrderDiagnostic,
} from '../diagnostics/types'

export function provideSuggestionCodeActions(
  _state: State,
  params: CodeActionParams,
  diagnostic:
    | InvalidConfigPathDiagnostic
    | InvalidTailwindDirectiveDiagnostic
    | InvalidScreenDiagnostic
    | InvalidVariantDiagnostic
    | RecommendedVariantOrderDiagnostic
): CodeAction[] {
  return diagnostic.suggestions.map((suggestion) => ({
    title: `Replace with '${suggestion}'`,
    kind: 'quickfix', // CodeActionKind.QuickFix,
    diagnostics: [diagnostic],
    edit: {
      changes: {
        [params.textDocument.uri]: [
          {
            range: diagnostic.range,
            newText: suggestion,
          },
        ],
      },
    },
  }))
}

import type { CodeAction, CodeActionParams } from 'vscode-languageserver'
import { State } from '../util/state'
import { doValidate } from '../diagnostics/diagnosticsProvider'
import { rangesEqual } from '../util/rangesEqual'
import {
  DiagnosticKind,
  isInvalidApplyDiagnostic,
  AugmentedDiagnostic,
  isCssConflictDiagnostic,
  isInvalidConfigPathDiagnostic,
  isInvalidTailwindDirectiveDiagnostic,
  isInvalidScreenDiagnostic,
  isInvalidVariantDiagnostic,
  isRecommendedVariantOrderDiagnostic,
} from '../diagnostics/types'
import { flatten, dedupeBy } from '../util/array'
import { provideCssConflictCodeActions } from './provideCssConflictCodeActions'
import { provideInvalidApplyCodeActions } from './provideInvalidApplyCodeActions'
import { provideSuggestionCodeActions } from './provideSuggestionCodeActions'

async function getDiagnosticsFromCodeActionParams(
  state: State,
  params: CodeActionParams,
  only?: DiagnosticKind[]
): Promise<AugmentedDiagnostic[]> {
  let document = state.editor.documents.get(params.textDocument.uri)
  let diagnostics = await doValidate(state, document, only)

  return params.context.diagnostics
    .map((diagnostic) => {
      return diagnostics.find((d) => {
        return (
          d.code === diagnostic.code &&
          d.message === diagnostic.message &&
          rangesEqual(d.range, diagnostic.range)
        )
      })
    })
    .filter(Boolean)
}

export async function doCodeActions(state: State, params: CodeActionParams): Promise<CodeAction[]> {
  let diagnostics = await getDiagnosticsFromCodeActionParams(
    state,
    params,
    params.context.diagnostics
      .map((diagnostic) => diagnostic.code)
      .filter(Boolean) as DiagnosticKind[]
  )

  return Promise.all(
    diagnostics.map((diagnostic) => {
      if (isInvalidApplyDiagnostic(diagnostic)) {
        return provideInvalidApplyCodeActions(state, params, diagnostic)
      }

      if (isCssConflictDiagnostic(diagnostic)) {
        return provideCssConflictCodeActions(state, params, diagnostic)
      }

      if (
        isInvalidConfigPathDiagnostic(diagnostic) ||
        isInvalidTailwindDirectiveDiagnostic(diagnostic) ||
        isInvalidScreenDiagnostic(diagnostic) ||
        isInvalidVariantDiagnostic(diagnostic) ||
        isRecommendedVariantOrderDiagnostic(diagnostic)
      ) {
        return provideSuggestionCodeActions(state, params, diagnostic)
      }

      return []
    })
  )
    .then(flatten)
    .then((x) => dedupeBy(x, (item) => JSON.stringify(item.edit)))
}

import type { CodeAction, CodeActionParams, TextEdit, Range } from 'vscode-languageserver'
import { State } from '../util/state'
import { InvalidApplyDiagnostic } from '../diagnostics/types'
import { isCssDoc } from '../util/css'
import { getLanguageBoundaries } from '../util/getLanguageBoundaries'
import { getClassNameMeta } from '../util/getClassNameMeta'
import { getClassNameParts } from '../util/getClassNameAtPosition'
import { validateApply } from '../util/validateApply'
import { isWithinRange } from '../util/isWithinRange'
const dlv = require('dlv')
import type { Root, Source } from 'postcss'
import { absoluteRange } from '../util/absoluteRange'
import { removeRangesFromString } from '../util/removeRangesFromString'
import detectIndent from 'detect-indent'
import isObject from '../util/isObject'
import { cssObjToAst } from '../util/cssObjToAst'
import dset from 'dset'
import selectorParser from 'postcss-selector-parser'
import { flatten } from '../util/array'

export async function provideInvalidApplyCodeActions(
  state: State,
  params: CodeActionParams,
  diagnostic: InvalidApplyDiagnostic
): Promise<CodeAction[]> {
  let document = state.editor.documents.get(params.textDocument.uri)
  let documentText = document.getText()
  let cssRange: Range
  let cssText = documentText
  const { postcss } = state.modules
  let changes: TextEdit[] = []

  let totalClassNamesInClassList = diagnostic.className.classList.classList.split(/\s+/).length

  let className = diagnostic.className.className
  let classNameParts = getClassNameParts(state, className)
  let classNameInfo = dlv(state.classNames.classNames, classNameParts)

  if (Array.isArray(classNameInfo)) {
    return []
  }

  if (!isCssDoc(state, document)) {
    let languageBoundaries = getLanguageBoundaries(state, document)
    if (!languageBoundaries) return []
    cssRange = languageBoundaries.css.find((range) => isWithinRange(diagnostic.range.start, range))
    if (!cssRange) return []
    cssText = document.getText(cssRange)
  }

  try {
    await postcss
      .module([
        // TODO: use plain function?
        // @ts-ignore
        postcss.module.plugin('', (_options = {}) => {
          return (root: Root) => {
            root.walkRules((rule) => {
              if (changes.length) return false

              rule.walkAtRules('apply', (atRule) => {
                let atRuleRange = postcssSourceToRange(atRule.source)
                if (cssRange) {
                  atRuleRange = absoluteRange(atRuleRange, cssRange)
                }

                if (!isWithinRange(diagnostic.range.start, atRuleRange)) return undefined // true

                let ast = classNameToAst(
                  state,
                  classNameParts,
                  rule.selector,
                  diagnostic.className.classList.important
                )

                if (!ast) return false

                rule.after(ast.nodes)
                let insertedRule = rule.next()
                if (!insertedRule) return false

                if (totalClassNamesInClassList === 1) {
                  atRule.remove()
                } else {
                  changes.push({
                    range: diagnostic.className.classList.range,
                    newText: removeRangesFromString(
                      diagnostic.className.classList.classList,
                      diagnostic.className.relativeRange
                    ),
                  })
                }

                let ruleRange = postcssSourceToRange(rule.source)
                if (cssRange) {
                  ruleRange = absoluteRange(ruleRange, cssRange)
                }

                let outputIndent: string
                let documentIndent = detectIndent(cssText)

                changes.push({
                  range: ruleRange,
                  newText:
                    rule.toString() +
                    (insertedRule.raws.before || '\n\n') +
                    insertedRule
                      .toString()
                      .replace(/\n\s*\n/g, '\n')
                      .replace(/(@apply [^;\n]+)$/gm, '$1;')
                      .replace(/([^\s^]){$/gm, '$1 {')
                      .replace(/^\s+/gm, (m: string) => {
                        if (typeof outputIndent === 'undefined') outputIndent = m
                        return m.replace(new RegExp(outputIndent, 'g'), documentIndent.indent)
                      })
                      .replace(/^(\s+)(.*?[^{}]\n)([^\s}])/gm, '$1$2$1$3'),
                })

                return false
              })

              return undefined // true
            })
          }
        }),
      ])
      .process(cssText, { from: undefined })
  } catch (_) {
    return []
  }

  if (!changes.length) {
    return []
  }

  return [
    {
      title: 'Extract to new rule',
      kind: 'quickfix', // CodeActionKind.QuickFix,
      diagnostics: [diagnostic],
      edit: {
        changes: {
          [params.textDocument.uri]: changes,
        },
      },
    },
  ]
}

function postcssSourceToRange(source: Source): Range {
  return {
    start: {
      line: source.start.line - 1,
      character: source.start.column - 1,
    },
    end: {
      line: source.end.line - 1,
      character: source.end.column,
    },
  }
}

function classNameToAst(
  state: State,
  classNameParts: string[],
  selector: string,
  important: boolean = false
) {
  const baseClassName = classNameParts[classNameParts.length - 1]
  const validatedBaseClassName = validateApply(state, [baseClassName])
  if (validatedBaseClassName === null || validatedBaseClassName.isApplyable === false) {
    return null
  }
  const meta = getClassNameMeta(state, classNameParts)
  if (Array.isArray(meta)) return null
  let context = meta.context
  let pseudo = meta.pseudo
  const globalContexts = state.classNames.context
  const path = []

  for (let i = 0; i < classNameParts.length - 1; i++) {
    let part = classNameParts[i]
    let common = globalContexts[part]
    if (!common) return null
    if (state.screens.includes(part)) {
      path.push(`@screen ${part}`)
      context = context.filter((con) => !common.includes(con))
    }
  }

  path.push(...context)

  let obj = {}
  for (let i = 1; i <= path.length; i++) {
    dset(obj, path.slice(0, i), {})
  }

  selector = appendPseudosToSelector(selector, pseudo)
  if (selector === null) return null

  let rule = {
    [selector]: {
      [`@apply ${baseClassName}${important ? ' !important' : ''}`]: '',
    },
  }
  if (path.length) {
    dset(obj, path, rule)
  } else {
    obj = rule
  }

  return cssObjToAst(obj, state.modules.postcss)
}

function appendPseudosToSelector(selector: string, pseudos: string[]): string | null {
  if (pseudos.length === 0) return selector

  let canTransform = true

  let transformedSelector = selectorParser((selectors) => {
    flatten(selectors.split((_) => true)).forEach((sel) => {
      // @ts-ignore
      for (let i = sel.nodes.length - 1; i >= 0; i--) {
        // @ts-ignore
        if (sel.nodes[i].type !== 'pseudo') {
          break
          // @ts-ignore
        } else if (pseudos.includes(sel.nodes[i].value)) {
          canTransform = false
          break
        }
      }
      if (canTransform) {
        pseudos.forEach((p) => {
          // @ts-ignore
          sel.append(selectorParser.pseudo({ value: p }))
        })
      }
    })
  }).processSync(selector)

  if (!canTransform) return null

  return transformedSelector
}

import { State } from '../util/state'
import type {
  CodeActionParams,
  CodeAction,
} from 'vscode-languageserver'
import { CssConflictDiagnostic } from '../diagnostics/types'
import { joinWithAnd } from '../util/joinWithAnd'
import { removeRangesFromString } from '../util/removeRangesFromString'

export async function provideCssConflictCodeActions(
  _state: State,
  params: CodeActionParams,
  diagnostic: CssConflictDiagnostic
): Promise<CodeAction[]> {
  return [
    {
      title: `Delete ${joinWithAnd(
        diagnostic.otherClassNames.map(
          (otherClassName) => `'${otherClassName.className}'`
        )
      )}`,
      kind: 'quickfix', // CodeActionKind.QuickFix,
      diagnostics: [diagnostic],
      edit: {
        changes: {
          [params.textDocument.uri]: [
            {
              range: diagnostic.className.classList.range,
              newText: removeRangesFromString(
                diagnostic.className.classList.classList,
                diagnostic.otherClassNames.map(
                  (otherClassName) => otherClassName.relativeRange
                )
              ),
            },
          ],
        },
      },
    },
  ]
}

import fs from 'fs'
import path from 'path'
import resolve from 'resolve'
import detective from 'detective'

export function getModuleDependencies(modulePath: string): string[] {
  return _getModuleDependencies(modulePath)
    .map(({ file }) => file)
    .filter((file) => file !== modulePath)
}

function createModule(file) {
  const source = fs.readFileSync(file, 'utf-8')
  const requires = detective(source)

  return { file, requires }
}

function _getModuleDependencies(entryFile) {
  const rootModule = createModule(entryFile)
  const modules = [rootModule]

  // Iterate over the modules, even when new
  // ones are being added
  for (const mdl of modules) {
    mdl.requires
      .filter((dep) => {
        // Only track local modules, not node_modules
        return dep.startsWith('./') || dep.startsWith('../')
      })
      .forEach((dep) => {
        try {
          const basedir = path.dirname(mdl.file)
          const depPath = resolve.sync(dep, { basedir })
          const depModule = createModule(depPath)

          modules.push(depModule)
        } catch (_err) {
          // eslint-disable-next-line no-empty
        }
      })
  }

  return modules
}

let postcss = require('postcss')
const esmImport = require('esm')(module)
const process = esmImport('../src/class-names/extractClassNames.js')
postcss = postcss([postcss.plugin('no-op', () => () => {})])

const processCss = async (css) =>
  process(await postcss.process(css, { from: undefined }))

test('processes default container plugin', async () => {
  const result = await processCss(`
    .container {
      width: 100%
    }

    @media (min-width: 640px) {
      .container {
        max-width: 640px
      }
    }

    @media (min-width: 768px) {
      .container {
        max-width: 768px
      }
    }

    @media (min-width: 1024px) {
      .container {
        max-width: 1024px
      }
    }

    @media (min-width: 1280px) {
      .container {
        max-width: 1280px
      }
    }
  `)
  expect(result).toEqual({
    context: {},
    classNames: {
      container: [
        { __context: [], __rule: true, __scope: null, width: '100%' },
        {
          __rule: true,
          __scope: null,
          __context: ['@media (min-width: 640px)'],
          'max-width': '640px',
        },
        {
          __rule: true,
          __scope: null,
          __context: ['@media (min-width: 768px)'],
          'max-width': '768px',
        },
        {
          __rule: true,
          __scope: null,
          __context: ['@media (min-width: 1024px)'],
          'max-width': '1024px',
        },
        {
          __rule: true,
          __scope: null,
          __context: ['@media (min-width: 1280px)'],
          'max-width': '1280px',
        },
      ],
    },
  })
})

test('foo', async () => {
  const result = await processCss(`
    @media (min-width: 640px) {
      .sm__TAILWIND_SEPARATOR__bg-red {
        background-color: red;
      }
      .sm__TAILWIND_SEPARATOR__hover__TAILWIND_SEPARATOR__bg-red:hover {
        background-color: red;
      }
    }
    .hover__TAILWIND_SEPARATOR__bg-red:hover {
      background-color: red;
    }
  `)

  expect(result).toEqual({
    context: {
      sm: ['@media (min-width: 640px)'],
      hover: [':hover'],
    },
    classNames: {
      sm: {
        'bg-red': {
          __rule: true,
          __scope: null,
          __context: ['@media (min-width: 640px)'],
          'background-color': 'red',
        },
        hover: {
          'bg-red': {
            __rule: true,
            __scope: null,
            __context: ['@media (min-width: 640px)'],
            __pseudo: [':hover'],
            'background-color': 'red',
          },
        },
      },
      hover: {
        'bg-red': {
          __rule: true,
          __scope: null,
          __pseudo: [':hover'],
          __context: [],
          'background-color': 'red',
        },
      },
    },
  })
})

test('processes basic css', async () => {
  const result = await processCss(`
    .bg-red {
      background-color: red;
    }
  `)

  expect(result).toEqual({
    context: {},
    classNames: {
      'bg-red': {
        __rule: true,
        __scope: null,
        __context: [],
        'background-color': 'red',
      },
    },
  })
})

test('processes pseudo selectors', async () => {
  const result = await processCss(`
    .bg-red:first-child::after {
      background-color: red;
    }
  `)

  expect(result).toEqual({
    context: {},
    classNames: {
      'bg-red': {
        __rule: true,
        __scope: null,
        __context: [],
        __pseudo: [':first-child', '::after'],
        'background-color': 'red',
      },
    },
  })
})

test('processes pseudo selectors in scope', async () => {
  const result = await processCss(`
    .scope:hover .bg-red {
      background-color: red;
    }
  `)

  expect(result).toEqual({
    context: {},
    classNames: {
      scope: {
        __context: [],
        __pseudo: [':hover'],
        __scope: null,
      },
      'bg-red': {
        __context: [],
        __rule: true,
        __scope: '.scope:hover',
        'background-color': 'red',
      },
    },
  })
})

test('processes multiple class names in the same rule', async () => {
  const result = await processCss(`
    .bg-red,
    .bg-red-again {
      background-color: red;
    }
  `)

  expect(result).toEqual({
    context: {},
    classNames: {
      'bg-red': {
        __rule: true,
        __scope: null,
        __context: [],
        'background-color': 'red',
      },
      'bg-red-again': {
        __rule: true,
        __scope: null,
        __context: [],
        'background-color': 'red',
      },
    },
  })
})

test('processes media queries', async () => {
  const result = await processCss(`
    @media (min-width: 768px) {
      .bg-red {
        background-color: red;
      }
    }
  `)

  expect(result).toEqual({
    context: {},
    classNames: {
      'bg-red': {
        __rule: true,
        __scope: null,
        __context: ['@media (min-width: 768px)'],
        'background-color': 'red',
      },
    },
  })
})

test('processes nested at-rules', async () => {
  const result = await processCss(`
    @supports (display: grid) {
      @media (min-width: 768px) {
        .bg-red {
          background-color: red;
        }
      }
    }
  `)

  expect(result).toEqual({
    context: {},
    classNames: {
      'bg-red': {
        __rule: true,
        __scope: null,
        __context: ['@supports (display: grid)', '@media (min-width: 768px)'],
        'background-color': 'red',
      },
    },
  })
})

test('merges declarations', async () => {
  const result = await processCss(`
    .bg-red {
      background-color: red;
    }
    .bg-red {
      color: white;
    }
  `)

  expect(result).toEqual({
    context: {},
    classNames: {
      'bg-red': {
        __rule: true,
        __scope: null,
        __context: [],
        'background-color': 'red',
        color: 'white',
      },
    },
  })
})

test('processes class name scope', async () => {
  const result = await processCss(`
    .scope .bg-red {
      background-color: red;
    }
  `)

  expect(result).toEqual({
    context: {},
    classNames: {
      scope: {
        __context: [],
        __scope: null,
      },
      'bg-red': {
        __rule: true,
        __context: [],
        __scope: '.scope',
        'background-color': 'red',
      },
    },
  })
})

test('processes multiple scopes for the same class name', async () => {
  const result = await processCss(`
    .scope1 .bg-red {
      background-color: red;
    }
    .scope2 + .bg-red {
      background-color: red;
    }
    .scope3 > .bg-red {
      background-color: red;
    }
  `)

  expect(result).toEqual({
    context: {},
    classNames: {
      scope1: { __context: [], __scope: null },
      scope2: { __context: [], __scope: null },
      scope3: { __context: [], __scope: null },
      'bg-red': [
        {
          __rule: true,
          __context: [],
          __scope: '.scope1',
          'background-color': 'red',
        },
        {
          __rule: true,
          __context: [],
          __scope: '.scope2 +',
          'background-color': 'red',
        },
        {
          __rule: true,
          __context: [],
          __scope: '.scope3 >',
          'background-color': 'red',
        },
      ],
    },
  })
})

test('processes multiple properties of the same name', async () => {
  const result = await processCss(`
    .bg-red {
      background-color: blue;
      background-color: red;
    }
  `)

  expect(result).toEqual({
    context: {},
    classNames: {
      'bg-red': {
        __rule: true,
        __context: [],
        __scope: null,
        'background-color': ['blue', 'red'],
      },
    },
  })
})

